// Helper function to determine if a number is prime
function IsPrime(n: int) : bool
    requires n >= 0
    ensures (result == true) ==> (n > 1 && forall i: int :: 2 <= i < n ==> n % i != 0)
    ensures (result == false) ==> (n < 2 || exists i: int :: 2 <= i < n && n % i == 0)
{
    if n < 2 {
        return false;
    }
    var i := 2;
    while i * i <= n
        invariant 2 <= i <= n
        invariant forall j: int :: 2 <= j < i ==> n % j != 0
    {
        if n % i == 0 {
            return false;
        }
        i := i + 1;
    }
    return true;
}
